import{_ as p,a0 as o,w as r,s as d,ao as l,I as i,x as e,a1 as n,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Telnet，爱一直在 | LCTT x X-CMD","titleTemplate":false,"description":"Telnet，爱一直在 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Telnet，爱一直在 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Telnet，爱一直在 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20171231 Why You Should Still Love Telnet","title":"Telnet，爱一直在","tag":"201802","desc":""},"relativePath":"201802/20171231 Why You Should Still Love Telnet.md","filePath":"[post].md"}'),c={name:"201802/20171231 Why You Should Still Love Telnet.md"};function h(g,s,b,m,k,u){const a=o("Link");return r(),d("div",null,[s[21]||(s[21]=l('<h1 id="telnet-爱一直在" tabindex="-1">Telnet，爱一直在 <a class="header-anchor" href="#telnet-爱一直在" aria-label="Permalink to “Telnet，爱一直在”">​</a></h1><p>Telnet，是系统管理员登录远程服务器的一种协议和工具。然而，由于所有的通信都没有加密，包括密码，都是明文发送的。Telnet 在 SSH 被开发出来之后就基本弃用了。</p><p>登录远程服务器，你可能不会也从未考虑过它。但这并不意味着 <code>telnet</code> 命令在调试远程连接问题时不是一个实用的工具。</p><p>本教程中，我们将探索使用 <code>telnet</code> 解决所有常见问题：“我怎么又连不上啦？”</p><p>这种讨厌的问题通常会在安装了像 Web服务器、邮件服务器、ssh 服务器、Samba 服务器等诸如此类的事之后遇到，用户无法连接服务器。</p><p><code>telnet</code> 不会解决问题但可以很快缩小问题的范围。</p><p><code>telnet</code> 用来调试网络问题的简单命令和语法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>telnet &lt;hostname or IP&gt; &lt;port&gt;</span></span></code></pre></div><p>因为 <code>telnet</code> 最初通过端口建立连接不会发送任何数据，适用于任何协议，包括加密协议。</p><p>连接问题服务器有四个可能会遇到的主要问题。我们会研究这四个问题，研究它们意味着什么以及如何解决。</p>',10)),i("p",null,[s[1]||(s[1]=e("本教程默认已经在 ",-1)),s[2]||(s[2]=i("code",null,"samba.example.com",-1)),s[3]||(s[3]=e(" 安装了 ",-1)),n(a,{href:"https://www.samba.org/"},{default:t(()=>[...s[0]||(s[0]=[e("Samba",-1)])]),_:1}),s[4]||(s[4]=e(" 服务器而且本地客户无法连上服务器。",-1))]),s[22]||(s[22]=l(`<h3 id="error-1-连接挂起" tabindex="-1">Error 1 - 连接挂起 <a class="header-anchor" href="#error-1-连接挂起" aria-label="Permalink to “Error 1 - 连接挂起”">​</a></h3><p>首先，我们需要试着用 <code>telnet</code> 连接 Samba 服务器。使用下列命令 (Samba 监听端口445)：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>telnet samba.example.com 445</span></span></code></pre></div><p>有时连接会莫名停止：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>telnet samba.example.com 445</span></span>
<span class="line"><span>Trying 172.31.25.31...</span></span></code></pre></div><p>这意味着 <code>telnet</code> 没有收到任何回应来建立连接。有两个可能的原因：</p><ol><li>你和服务器之间有个路由器宕掉了。</li><li>防火墙拦截了你的请求。</li></ol>`,7)),i("p",null,[s[6]||(s[6]=e("为了排除第 1 点，对服务器上进行一个快速 ",-1)),n(a,{href:"https://www.systutorials.com/docs/linux/man/8-mtr/"},{default:t(()=>[...s[5]||(s[5]=[i("code",null,"mtr samba.example.com",-1)])]),_:1}),s[7]||(s[7]=e(" 。如果服务器是可达的，那么便是防火墙（注意：防火墙总是存在的）。",-1))]),s[23]||(s[23]=l(`<p>首先用 <code>iptables -L -v -n</code> 命令检查服务器本身有没有防火墙，没有的话你能看到以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iptables -L -v -n</span></span>
<span class="line"><span>Chain INPUT (policy ACCEPT 0 packets, 0 bytes)</span></span>
<span class="line"><span> pkts bytes target prot opt in out source destination</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Chain FORWARD (policy ACCEPT 0 packets, 0 bytes)</span></span>
<span class="line"><span> pkts bytes target prot opt in out source destination</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Chain OUTPUT (policy ACCEPT 0 packets, 0 bytes)</span></span>
<span class="line"><span> pkts bytes target prot opt in out source destination</span></span></code></pre></div><p>如果你看到其他东西那可能就是问题所在了。为了检验，停止 <code>iptables</code> 一下并再次运行 <code>telnet samba.example.com 445</code> 看看你是否能连接。如果你还是不能连接看看你的提供商或企业有没有防火墙拦截你。</p><h3 id="error-2-dns-问题" tabindex="-1">Error 2 - DNS 问题 <a class="header-anchor" href="#error-2-dns-问题" aria-label="Permalink to “Error 2 - DNS 问题”">​</a></h3><p>DNS 问题通常发生在你正使用的主机名没有解析到 IP 地址。错误如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>telnet samba.example.com 445</span></span>
<span class="line"><span>Server lookup failure: samba.example.com:445, Name or service not known</span></span></code></pre></div><p>第一步是把主机名替换成服务器的 IP 地址。如果你可以连上那么就是主机名的问题。</p><p>有很多发生的原因（以下是我见过的）：</p><ol><li>域名注册了吗？用 <code>whois</code> 来检验。</li><li>域名过期了吗？用 <code>whois</code> 来检验。</li><li>是否使用正确的主机名？用 <code>dig</code> 或 <code>host</code> 来确保你使用的主机名解析到正确的 IP。</li><li>你的 <strong>A</strong> 记录正确吗？确保你没有偶然创建类似 <code>smaba.example.com</code> 的 <strong>A</strong> 记录。</li></ol><p>一定要多检查几次拼写和主机名是否正确（是 <code>samba.example.com</code> 还是 <code>samba1.example.com</code>）？这些经常会困扰你，特别是比较长、难记或其它国家的主机名。</p><h3 id="error-3-服务器没有侦听端口" tabindex="-1">Error 3 - 服务器没有侦听端口 <a class="header-anchor" href="#error-3-服务器没有侦听端口" aria-label="Permalink to “Error 3 - 服务器没有侦听端口”">​</a></h3><p>这种错误发生在 <code>telnet</code> 可达服务器但是指定端口没有监听。就像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>telnet samba.example.com 445</span></span>
<span class="line"><span>Trying 172.31.25.31...</span></span>
<span class="line"><span>telnet: Unable to connect to remote host: Connection refused</span></span></code></pre></div><p>有这些原因：</p><ol><li>你 <strong>确定</strong> 连接的是正确的服务器？</li><li>你的应用服务器没有侦听预期的端口。在服务器上运行 <code>netstat -plunt</code> 来查看它究竟在干什么并看哪个端口才是对的，实际正在监听中的。</li><li>应用服务器没有运行。这可能突然而又悄悄地发生在你启动应用服务器之后。启动服务器运行 <code>ps auxf</code> 或 <code>systemctl status application.service</code> 查看运行。</li></ol><h3 id="error-4-连接被服务器关闭" tabindex="-1">Error 4 - 连接被服务器关闭 <a class="header-anchor" href="#error-4-连接被服务器关闭" aria-label="Permalink to “Error 4 - 连接被服务器关闭”">​</a></h3><p>这种错误发生在连接成功建立但是应用服务器建立的安全措施一连上就将其结束。错误如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>telnet samba.example.com 445</span></span>
<span class="line"><span>Trying 172.31.25.31...</span></span>
<span class="line"><span>Connected to samba.example.com.</span></span>
<span class="line"><span>Escape character is &#39;^]&#39;.</span></span>
<span class="line"><span>Connection closed by foreign host.</span></span></code></pre></div><p>最后一行 <code>Connection closed by foreign host.</code> 意味着连接被服务器主动终止。为了修复这个问题，需要看看应用服务器的安全设置确保你的 IP 或用户允许连接。</p><h3 id="成功连接" tabindex="-1">成功连接 <a class="header-anchor" href="#成功连接" aria-label="Permalink to “成功连接”">​</a></h3><p>成功的 <code>telnet</code> 连接如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>telnet samba.example.com 445</span></span>
<span class="line"><span>Trying 172.31.25.31...</span></span>
<span class="line"><span>Connected to samba.example.com.</span></span>
<span class="line"><span>Escape character is &#39;^]&#39;.</span></span></code></pre></div><p>连接会保持一段时间只要你连接的应用服务器时限没到。</p><p>输入 <code>CTRL+]</code> 中止连接，然后当你看到 <code>telnet&gt;</code> 提示，输入 <code>quit</code> 并按回车：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>telnet samba.example.com 445</span></span>
<span class="line"><span>Trying 172.31.25.31...</span></span>
<span class="line"><span>Connected to samba.example.com.</span></span>
<span class="line"><span>Escape character is &#39;^]&#39;.</span></span>
<span class="line"><span>^]</span></span>
<span class="line"><span>telnet&gt; quit</span></span>
<span class="line"><span>Connection closed.</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>客户程序连不上服务器的原因有很多。确切原因很难确定，特别是当客户是图形用户界面提供很少或没有错误信息。用 <code>telnet</code> 并观察输出可以让你很快确定问题所在节约很多时间。</p><hr>`,28)),i("p",null,[s[9]||(s[9]=e("via: ",-1)),n(a,{href:"https://bash-prompt.net/guides/telnet/"},{default:t(()=>[...s[8]||(s[8]=[e("https://bash-prompt.net/guides/telnet/",-1)])]),_:1})]),i("p",null,[s[13]||(s[13]=e("作者：",-1)),n(a,{href:"https://bash-prompt.net"},{default:t(()=>[...s[10]||(s[10]=[e("Elliot Cooper",-1)])]),_:1}),s[14]||(s[14]=e(" 译者：",-1)),n(a,{href:"https://github.com/XYenChi"},{default:t(()=>[...s[11]||(s[11]=[e("XYenChi",-1)])]),_:1}),s[15]||(s[15]=e(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[12]||(s[12]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[18]||(s[18]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[16]||(s[16]=[e("LCTT",-1)])]),_:1}),s[19]||(s[19]=e(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:t(()=>[...s[17]||(s[17]=[e("Linux中国",-1)])]),_:1}),s[20]||(s[20]=e(" 荣誉推出",-1))])])}const y=p(c,[["render",h]]);export{C as __pageData,y as default};
